// Sub-sectors: groups inside a sector that the office uses but the Act does not
// (first one: Gold board applications, offices for the sale of gold, under Infrastructure).
//
// A facility's sub-sector is its `sub_sector` field when set ('none' = deliberately none);
// otherwise it is read from what the facility does, the same way the fee estimate reads it,
// so gold trading facilities are found before anyone has tagged them.

import { matchRules } from './revenueForecast.mjs'

export const SUB_SECTORS = [
  { value: 'gold_board', name: 'Gold board applications', sector: 'CI', rules: ['gold1', 'gold2'] },
]

export const SUB_SECTOR_NONE = 'none'

export function subSectorName(value) {
  return SUB_SECTORS.find((s) => s.value === value)?.name ?? ''
}

export function subSectorsFor(sectorPrefix) {
  return SUB_SECTORS.filter((s) => s.sector === sectorPrefix)
}

// { value, name, detected } or null.
export function facilitySubSector(facility) {
  const set = facility?.sub_sector
  if (set === SUB_SECTOR_NONE) return null
  if (set) {
    const s = SUB_SECTORS.find((x) => x.value === set)
    return s ? { value: s.value, name: s.name, detected: false } : null
  }
  const ids = new Set(matchRules(facility).map((r) => r.id))
  const s = SUB_SECTORS.find((x) => x.rules.some((id) => ids.has(id)))
  return s ? { value: s.value, name: s.name, detected: true } : null
}
